<Popover open={open} triggerRef={ref} role="menu" menuAlign="right" aria-label={...}>
  <div ref={menuRef} className={styles.cardMenu}>
    <button role="menuitem" className={styles.cardMenuItem} onClick={edit}>Edit</button>
    <button role="menuitem" className={styles.cardMenuItem} onClick={remove}>Delete</button>
