// StudyModesTab.module.css — item hover bằng opacity, không có focus state
.cardMenuItem { padding: var(--space-2) var(--space-2-5); transition: opacity ...; }
@media (hover: hover) { .cardMenuItem:hover { opacity: 0.75; } }

// + useEffect riêng cho outside-click/scroll/Escape
// → Popover mặc định radius: var(--radius-pill) nên list dọc thành khối tròn, item không có hover bg,
//   và menu không bám trigger (toạ độ đo 1 lần lúc mở).

cases.good:
// shared/ui/Menu.tsx — một chỗ duy nhất
<Popover variant="menu" role="menu" contentRef={menuRef} onKeyDown={handleKeyDown} ...>
  {children}
</Popover>
// MenuItem: role=menuitem(radio), hover/focus-visible = background: var(--color-surface-hover), :disabled opacity
// Menu: outside-click (composedPath vs trigger + menu), Escape, scroll, ArrowUp/Down/Home/End

// Call site
<Menu open={menuOpen} onClose={() => setMenuOpen(false)} triggerRef={menuTriggerRef} align="right" ariaLabel={t('studyModes.card.actions')}>
  <MenuItem icon={<Icon name="pencil" size="sm" />} onSelect={edit} data-cell-id={`edit-mode-${mode.id}`}>{t('studyModes.card.edit')}</MenuItem>
  <MenuItem icon={<Icon name="trash" size="sm" />} onSelect={remove} data-cell-id={`delete-mode-${mode.id}`}>{t('studyModes.card.delete')}</MenuItem>
</Menu>
